  1	/**
  2	  This ADT represents a multiset.
  3	 */
  4	trait MyMultiset {
  5	
  6	  // internal invariant
  7	  ghost predicate Valid()
  8	    reads this
  9	
 10	  // abstract variable
 11	  ghost var theMultiset: multiset<int>
 12	
 13	  method Add(elem: int) returns (didChange: bool)
 14	    modifies this
 15	    requires Valid()
 16	    ensures Valid()
 17	    ensures theMultiset == old(theMultiset) + multiset{elem}
 18	    ensures didChange
 19	
 20	  ghost predicate Contains(elem: int)
 21	    reads this
 22	  { elem in theMultiset }
 23	
 24	  method Remove(elem: int) returns (didChange: bool)
 25	    modifies this
 26	    requires Valid()
 27	    ensures Valid()
 28	    /* If the multiset contains the element */
 29	    ensures old(Contains(elem)) ==> theMultiset == old(theMultiset) - multiset{elem}
 30	    ensures old(Contains(elem)) ==> didChange
 31	    /* If the multiset does not contain the element */
 32	    ensures ! old(Contains(elem)) ==> theMultiset == old(theMultiset)
 33	    ensures ! old(Contains(elem)) ==> ! didChange
 34	
 35	  method Length() returns (len: int)
 36	    requires Valid()
 37	    ensures Valid()
 38	    ensures len == |theMultiset|
 39	
 40	  method equals(other: MyMultiset) returns (equal?: bool)
 41	    requires Valid()
 42	    requires other.Valid()
 43	    ensures Valid()
 44	    ensures equal? <==> theMultiset == other.theMultiset
 45	
 46	  method getElems() returns (elems: seq<int>)
 47	    requires Valid()
 48	    ensures Valid()
 49	    ensures multiset(elems) == theMultiset
 50	}
