 52	/**
 53	This implementation implements the ADT with a map.
 54	 */
 55	class MultisetImplementationWithMap extends MyMultiset {
 56	
 57	  // valid invariant predicate of the ADT implementation
 58	  ghost predicate Valid()
 59	    reads this
 60	  {
 61	    (forall i | i in elements.Keys :: elements[i] > 0) && (theMultiset == A(elements)) && (forall i :: i in elements.Keys <==> Contains(i))
 62	  }
 63	
 64	  // the abstraction function
 65	  function A(m: map<int, nat>): (s:multiset<int>)
 66	    ensures (forall i | i in m :: m[i] == A(m)[i]) && (m == map[] <==> A(m) == multiset{}) && (forall i :: i in m <==> i in A(m))
 67	
 68	  // lemma for the opposite of the abstraction function
 69	  lemma LemmaReverseA(m: map<int, nat>, s : seq<int>)
 70	    requires (forall i | i in m :: m[i] == multiset(s)[i]) && (m == map[] <==> multiset(s) == multiset{})
 71	    ensures A(m) == multiset(s)
 72	
 73	  // ADT concrete implementation variable
 74	  var elements: map<int, nat>;
 75	
 76	  // constructor of the implementation class that ensures the implementation invariant
 77	  constructor MultisetImplementationWithMap()
 78	    ensures Valid()
 79	    ensures elements == map[]
 80	    ensures theMultiset == multiset{}
 81	  {
 82	    elements := map[];
 83	    theMultiset := multiset{};
 84	  }
 85	//adds an element to the multiset
 86	  method Add(elem: int) returns (didChange: bool)
 87	    modifies this
 88	    requires Valid()
 89	    ensures elem in elements ==> elements == elements[elem := elements[elem]]
 90	    ensures theMultiset == old(theMultiset) + multiset{elem}
 91	    ensures !(elem in elements) ==> elements == elements[elem := 1]
 92	    ensures didChange
 93	    ensures Contains(elem)
 94	    ensures Valid()
 95	  {
 96	    if !(elem in elements) {
 97	      elements := elements[elem := 1];
 98	    } else {
 99	      elements := elements[elem := (elements[elem] + 1)];
100	    }
101	    
102	    didChange := true;
103	
104	    theMultiset := A(elements);
105	  }
106	
107	//removes an element from the multiset
108	  method Remove(elem: int) returns (didChange: bool)
109	    modifies this
110	    requires Valid()
111	    ensures Valid()
112	   /* If the multiset contains the element */
113	    ensures old(Contains(elem)) ==> theMultiset == old(theMultiset) - multiset{elem}
114	    ensures old(Contains(elem)) ==> didChange
115	    /* If the multiset does not contain the element */
116	    ensures ! old(Contains(elem)) ==> theMultiset == old(theMultiset)
117	    ensures ! old(Contains(elem)) ==> ! didChange
118	    ensures didChange <==> elements != old(elements)
119	  {
120	    /* If the multiset does not contain the element */
121	    if elem !in elements {
122	      assert ! Contains(elem);
123	      assert theMultiset == old(theMultiset);
124	      assert Valid();
125	      return false;
126	    }
127	
128	    /* If the multiset contains the element */
129	    assert Contains(elem);
130	    elements := elements[elem := elements[elem] - 1];
131	
132	    if(elements[elem] == 0) {
133	      elements := elements - {elem};
134	    }
135	
136	    theMultiset := A(elements);
137	    didChange := true;
138	  }
139	
140	//gets the length of the multiset
141	  method Length() returns (len: int)
142	    requires Valid()
143	    ensures len == |theMultiset|
144	  {
145	    var result := Map2Seq(elements);
146	    return |result|;
147	  }
148	
149	//compares the current multiset with another multiset and determines if they're equal
150	  method equals(other: MyMultiset) returns (equal?: bool)
151	    requires Valid()
152	    requires other.Valid()
153	    ensures Valid()
154	    ensures equal? <==> theMultiset == other.theMultiset
155	  {
156	    var otherMapSeq := other.getElems();
157	    assert multiset(otherMapSeq) == other.theMultiset;
158	    var c := this.getElems();
159	    return multiset(c) == multiset(otherMapSeq);
160	  }
161	
162	//gets the elements of the multiset as a sequence
163	  method getElems() returns (elems: seq<int>)
164	    requires Valid()
165	    ensures Valid()
166	    ensures multiset(elems) == theMultiset
167	  {
168	    var result : seq<int>;
169	    result := Map2Seq(elements);
170	    return result;
171	  }
172	
173	//Transforms a map to a sequence
174	  method Map2Seq(m: map<int, nat>) returns (s: seq<int>)
175	    requires forall i | i in m.Keys :: i in m.Keys <==> m[i] > 0
176	    ensures forall i | i in m.Keys :: multiset(s)[i] == m[i]
177	    ensures forall i | i in m.Keys :: i in s
178	    ensures A(m) == multiset(s)
179	    ensures (forall i | i in m :: m[i] == multiset(s)[i]) && (m == map[] <==> multiset(s) == multiset{})
180	  {
181	    if |m| == 0 {return []; }
182	
183	    var keys := m.Keys;
184	    var key: int;
185	    s := [];
186	
187	    while keys != {}
188	      invariant forall i | i in m.Keys :: i in keys <==> multiset(s)[i] == 0
189	      invariant forall i | i in m.Keys - keys :: multiset(s)[i] == m[i]
190	    {
191	
192	      key :| key in keys;
193	
194	      var counter := 0;
195	
196	      while counter < m[key]
197	        invariant 0 <= counter <= (m[key]) + 1
198	        invariant multiset(s)[key] == counter
199	        invariant forall i | i in m.Keys && i != key :: i in keys <==> multiset(s)[i] == 0
200	        invariant forall i | i in m.Keys - keys :: multiset(s)[i] == m[i];
201	      {
202	        s := s + [key];
203	        counter := counter + 1;
204	      }
205	
206	      keys := keys - {key};
207	
208	    }
209	    LemmaReverseA(m, s);
210	  }
211	
212	  method Test1()
213	    modifies this
214	  {
215	
216	    assume this.theMultiset == multiset{1, 2, 3, 4};
217	    assume this.Valid();
218	
219	    // get elements test
220	    var a := this.getElems();
221	    assert multiset(a) == multiset{1, 2, 3, 4};
222	
223	    //declaring the other bag
224	    var theOtherBag : MultisetImplementationWithMap;
225	    theOtherBag := new MultisetImplementationWithMap.MultisetImplementationWithMap();
226	
227	    // equals test - unequal bags
228	    var b:= this.equals(theOtherBag);
229	    assert b == false;
230	
231	    // equals test - equal bags
232	    theOtherBag.theMultiset := multiset{1, 2, 3, 4};
233	    theOtherBag.elements := map[1 := 1, 2:=1, 3:=1,4:=1];
234	    var c:= this.equals(theOtherBag);
235	    assert c == true;
236	  }
237	
238	  method Test2()
239	    modifies this
240	  {
241	
242	    assume this.theMultiset == multiset{1, 2, 3, 4};
243	    assume this.Valid();
244	
245	    // get elements test
246	    var a := this.getElems();
247	    assert multiset(a) == multiset{1, 2, 3, 4};
248	
249	    //add test
250	    var d := this.Add(3);
251	    var e := this.getElems();
252	    assert multiset(e) == multiset([1, 2, 3, 4, 3]);
253	
254	    //remove test
255	    var f := this.Remove(4);
256	    var g := this.getElems();
257	    assert multiset(g) == multiset([1, 2, 3, 3]);
258	
259	    //length test
260	    var h := this.Length();
261	    assert h == 4;
262	  }
263	
264	  method Test3()
265	  {
266	
267	    //test Map2Seq
268	    var m := map[2:= 2, 3:=3, 4:= 4];
269	    var s :seq<int> := [2, 2, 3, 3, 3, 4, 4,4 ,4];
270	
271	    var a := this.Map2Seq(m);
272	    assert multiset(a) == multiset(s);
273	
274	    var x := map[1 := 1, 2:= 1, 3:= 1];
275	    var y :seq<int> := [1, 2, 3];
276	
277	    var z := this.Map2Seq(x);
278	    assert multiset(z) == multiset(y);
279	
280	  }
281	}

